type alien_individual = {
  is_lawful_permanent_resident_during_year : bool; (* clause (i): lawful permanent resident at any time during calendar year *)
  meets_substantial_presence_test : bool; (* clause (ii): substantial presence test of paragraph (3) *)
  makes_first_year_election : bool; (* clause (iii): election under paragraph (4) *)
}

(* 7701(b)(1)(A) - alien treated as US resident for calendar year iff (i), (ii), or (iii) holds *)
let is_resident_alien (alien : alien_individual) : bool =
  alien.is_lawful_permanent_resident_during_year ||
  alien.meets_substantial_presence_test ||
  alien.makes_first_year_election

type individual = {
  establishes_closer_connection_to_foreign_country : bool; (* 7701(b)(2)(C)(i) claim *)
  days_present_with_closer_connection : int; (* days individual claims the closer-connection exception for *)
}

let max_disregarded_days = 10 (* 7701(b)(2)(C)(ii) cap *)

(* number of days of US presence disregarded under 7701(b)(2)(C) *)
let days_of_presence_disregarded (individual : individual) : int =
  if individual.establishes_closer_connection_to_foreign_country then
    min individual.days_present_with_closer_connection max_disregarded_days
  else 0

(* individual for substantial presence test, days present in current year and prior two years *)
type individual = {
  current_year_days : int;
  first_preceding_year_days : int;
  second_preceding_year_days : int;
}

(* 7701(b)(3)(A)(i) - present at least 31 days in current year *)
let is_present_31_days (person : individual) : bool =
  person.current_year_days >= 31

(* 7701(b)(3)(A)(ii) - weighted sum of days: current year x1, 1st preceding x1/3, 2nd preceding x1/6 *)
let weighted_day_count (person : individual) : float =
  (float_of_int person.current_year_days *. 1.0) +.
  (float_of_int person.first_preceding_year_days *. (1.0 /. 3.0)) +.
  (float_of_int person.second_preceding_year_days *. (1.0 /. 6.0))

let meets_weighted_day_threshold (person : individual) : bool =
  weighted_day_count person >=. 183.0

(* 7701(b)(3)(A) - substantial presence test: both (i) and (ii) must hold *)
let meets_substantial_presence_test (person : individual) : bool =
  is_present_31_days person && meets_weighted_day_threshold person

