type day = {
  date : string;
}

(* (A) baseline test: physically present in US at any time during day *)
let is_physically_present_in_us (individual : individual) (day : day) : bool =
  (* placeholder: raw physical presence fact for the day *)
  failwith "unspecified physical presence data"

(* (B) Canada/Mexico commuter exception *)
let is_commuting_from_canada_or_mexico (individual : individual) (day : day) : bool =
  let regularly_commutes_to_us_employment (individual : individual) : bool =
    failwith "unspecified regular commuting pattern"
  in
  let resides_in_canada_or_mexico (individual : individual) : bool =
    failwith "unspecified place of residence"
  in
  let commutes_on_day (individual : individual) (day : day) : bool =
    failwith "unspecified commuting activity for day"
  in
  regularly_commutes_to_us_employment individual
  && resides_in_canada_or_mexico individual
  && commutes_on_day individual day

(* (C) transit-between-two-foreign-points exception *)
let is_in_transit_between_foreign_points (individual : individual) (day : day) : bool =
  let is_in_transit_between_two_foreign_points (individual : individual) (day : day) : bool =
    failwith "unspecified transit status"
  in
  let hours_physically_present_in_us (individual : individual) (day : day) : float =
    failwith "unspecified hours present"
  in
  is_in_transit_between_two_foreign_points individual day
  && hours_physically_present_in_us individual day <. 24.0

(* (D) foreign vessel crew member exception *)
let is_temporarily_present_crew_member (individual : individual) (day : day) : bool =
  let is_regular_crew_member_of_foreign_vessel (individual : individual) : bool =
    failwith "unspecified crew membership"
  in
  let vessel_engaged_in_us_foreign_transport (individual : individual) : bool =
    failwith "unspecified vessel route"
  in
  let temporarily_present_as_crew (individual : individual) (day : day) : bool =
    failwith "unspecified crew presence for day"
  in
  let engages_in_trade_or_business_in_us (individual : individual) (day : day) : bool =
    failwith "unspecified trade or business activity"
  in
  is_regular_crew_member_of_foreign_vessel individual
  && vessel_engaged_in_us_foreign_transport individual
  && temporarily_present_as_crew individual day
  && not (engages_in_trade_or_business_in_us individual day)

(* 7701(b)(7): presence in United States on a given day, subject to
   commuter, transit, and crew exceptions overriding the baseline physical-presence test *)
let is_present_in_united_states (individual : individual) (day : day) : bool =
  if is_commuting_from_canada_or_mexico individual day then false
  else if is_in_transit_between_foreign_points individual day then false
  else if is_temporarily_present_crew_member individual day then false
  else is_physically_present_in_us individual day

